style.css:
@-moz-document domain("youtube.com") {
/* SUA AURORA NO FUNDO */
    html, body, #page-manager, ytd-app, 
    ytd-browse, #content.ytd-app,
    #masthead-container.ytd-app, #background.ytd-masthead {
        background-color: #0c0817 !important;
        background-image: 
            linear-gradient(35deg, transparent 60%, rgba(74, 20, 140, 0.8) 65%, rgba(106, 27, 154, 0.9) 70%, transparent 75%),
            linear-gradient(-25deg, transparent 40%, rgba(0, 188, 212, 0.8) 45%, rgba(132, 255, 255, 0.9) 52%, transparent 58%),
            linear-gradient(15deg, transparent 25%, rgba(233, 30, 99, 0.85) 32%, rgba(244, 143, 177, 0.95) 38%, transparent 45%) !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        box-shadow: inset 0 -300px 300px rgba(186, 104, 200, 0.15) !important;
    }

    /* TARJA FIXA NO MEIO PARA FORÇAR O TEXTO A APARECER */
    body::before {
        content: "OMG ITZ A FHOKING AURORA!!!!!";
        position: fixed !important;
        top: 0 !important;
        left: 0 !important;
        width: 100% !important;
        background: #000000 !important; /* Fundo preto para destacar bem */
        color: #ffffff !important;
        text-align: center !important;
        font-family:'Arial Black', sans-serif !important;
        font-size: 26px !important; /* Letra grande */
        padding: 10px 0 !important;
        letter-spacing: 3px !important;
        text-shadow: 0 0 10px #00bcd4, 0 0 20px #e91e63 !important;
        z-index: 999999 !important;
        box-shadow: 0 4px 15px rgba(0,0,0,0.5) !important;
    }

    /* Empurra o site um pouco para baixo para a tarja não cobrir os botões do YouTube */
    ytd-app {
        margin-top: 50px !important;
    }

    /* TRANSPARÊNCIAS */
    ytd-rich-grid-renderer, ytd-guide-renderer, 
    #guide-content.ytd-app, ytd-playlist-video-list-renderer,
    ytd-watch-flexy {
        background: transparent !important;
    }

    #masthead-container.ytd-app, #contentContainer.ytd-app, ytd-mini-guide-renderer {
        background: rgba(12, 8, 23, 0.6) !important;
        backdrop-filter: blur(8px) !important;
    }
}
